(4190958, 602490, 15711, '<td valign="top">Nice tones and leading line!! The horizon is slightly tilted to the left.</td>', 'Nice tones and leading line!! The horizon is slightly tilted to the left.', '2007-10-24 01:05:35.000000', NULL, 1),
(4190960, 603357, 15711, '<td valign="top">Lovely.  The pinky/salmon color is so beautiful. Love the blur of the wings.  Classic.</td>', 'Lovely.  The pinky/salmon color is so beautiful. Love the blur of the wings.  Classic.', '2007-10-24 01:05:55.000000', NULL, 1),
(4190965, 602918, 15711, '<td valign="top">Really nice.  I like her thoughtful expression in contrast to the blatant graffiti on the train.  Nicely composed.</td>', 'Really nice.  I like her thoughtful expression in contrast to the blatant graffiti on the train.  Nicely composed.', '2007-10-24 01:06:20.000000', NULL, 1),
(4190968, 602696, 15711, '<td valign="top">Nice balance with the old wood in the foreground. beautiful sky!!!</td>', 'Nice balance with the old wood in the foreground. beautiful sky!!!', '2007-10-24 01:06:53.000000', NULL, 1),
(4190974, 602219, 15711, '<td valign="top">The pop of the color in her scarf really zeros you in on her. The centering of her head is perfect for the shot.  Nicely done.</td>', 'The pop of the color in her scarf really zeros you in on her. The centering of her head is perfect for the shot.  Nicely done.', '2007-10-24 01:07:48.000000', NULL, 1),
(4190976, 603863, 57320, '<td valign="top">Cute! Nice job</td>', 'Cute! Nice job', '2007-10-24 01:08:12.000000', NULL, 1),
(4190977, 604003, 15711, '<td valign="top">Lovely.  That sky is killer.</td>', 'Lovely.  That sky is killer.', '2007-10-24 01:08:16.000000', NULL, 1),
(4190981, 603640, 57320, '<td valign="top">Lovley lovley lovley!</td>', 'Lovley lovley lovley!', '2007-10-24 01:08:30.000000', NULL, 1),
