(4194354, 604099, 49578, '<td valign="top">Good concept.<br/>I feel couloured rendering would have done justice. <br/>Lighting looks flat and composition could have been better</td>', 'Good concept.I feel couloured rendering would have done justice. Lighting looks flat and composition could have been better', '2007-10-25 02:35:42.000000', NULL, 1),
(4194355, 601944, 49578, '<td valign="top">The clouds and the rays form an interesting composition but the silhouette of the tree does not add to it too much IMO.</td>', 'The clouds and the rays form an interesting composition but the silhouette of the tree does not add to it too much IMO.', '2007-10-25 02:37:25.000000', NULL, 1),
(4194358, 603382, 49578, '<td valign="top">The sky is flat and not too interesting, maybe including lesser of it could have helped? Horizon line at 1/3 distance from top could be an alternative</td>', 'The sky is flat and not too interesting, maybe including lesser of it could have helped? Horizon line at 1/3 distance from top could be an alternative', '2007-10-25 02:38:52.000000', NULL, 1),
