(4194361, 602101, 49578, '<td valign="top">The bee/fly should have been more in focus</td>', 'The bee/fly should have been more in focus', '2007-10-25 02:40:14.000000', NULL, 1),
(4194363, 603806, 49578, '<td valign="top">Nice candle light! I love the warm feel.<br/> <br/>Where''s the bottle of ink? ;) Just kiddin!</td>', 'Nice candle light! I love the warm feel. Where''s the bottle of ink? ;) Just kiddin!', '2007-10-25 02:41:30.000000', NULL, 1),
(4194364, 603863, 49578, '<td valign="top">I love the DoF and the composition</td>', 'I love the DoF and the composition', '2007-10-25 02:42:24.000000', NULL, 1),
(4194369, 603571, 49578, '<td valign="top">Interesting concept and good composition. The pathway leads the eye from the front to the back. But i dont quite like the out of focus grass right at the front of the picture. Also the green could have been a bit more vivid?</td>', 'Interesting concept and good composition. The pathway leads the eye from the front to the back. But i dont quite like the out of focus grass right at the front of the picture. Also the green could have been a bit more vivid?', '2007-10-25 02:44:40.000000', NULL, 1),
(4194371, 603033, 49578, '<td valign="top">I''m afraid i don''t like the composition as well as the exposure</td>', 'I''m afraid i don''t like the composition as well as the exposure', '2007-10-25 02:46:03.000000', NULL, 1),
(4194372, 604122, 49578, '<td valign="top">Pardon me for my ignorance, but i fail to see the concept of "distance" here</td>', 'Pardon me for my ignorance, but i fail to see the concept of "distance" here', '2007-10-25 02:46:47.000000', NULL, 1),
(4194374, 604130, 49578, '<td valign="top">I like the way the colour changes from blue to red to brown from back to front, and i get a feeling of something really distant. But i feel there is an overall  lack of sharpness in the picture</td>', 'I like the way the colour changes from blue to red to brown from back to front, and i get a feeling of something really distant. But i feel there is an overall  lack of sharpness in the picture', '2007-10-25 02:48:55.000000', NULL, 1),
