(4194376, 603963, 49578, '<td valign="top">not sharp enough.</td>', 'not sharp enough.', '2007-10-25 02:50:31.000000', NULL, 1),
(4194378, 603181, 49578, '<td valign="top">umm. no focus, no sharpness, lot of grain, that''s about the image quality. The picture itself also does not seem any interesting</td>', 'umm. no focus, no sharpness, lot of grain, that''s about the image quality. The picture itself also does not seem any interesting', '2007-10-25 02:51:47.000000', NULL, 1),
