(4194380, 603742, 49578, '<td valign="top">Like the lighting</td>', 'Like the lighting', '2007-10-25 02:52:59.000000', NULL, 1),
(4194382, 604113, 49578, '<td valign="top">There is a lack of a specific leading light in this picture. The red light trail is there of course but i feel the leading line of the road should have come out stronger</td>', 'There is a lack of a specific leading light in this picture. The red light trail is there of course but i feel the leading line of the road should have come out stronger', '2007-10-25 02:56:00.000000', NULL, 1),
(4194386, 601936, 49578, '<td valign="top">could you have not done anything about those poles? This is such a beautiful picture and then these two things here are such a distraction!</td>', 'could you have not done anything about those poles? This is such a beautiful picture and then these two things here are such a distraction!', '2007-10-25 02:58:22.000000', NULL, 1),
(4194388, 603989, 49578, '<td valign="top">This would have been so good without the flash!</td>', 'This would have been so good without the flash!', '2007-10-25 03:00:14.000000', NULL, 1),
