(4194940, 602745, 58728, '<td valign="top">My fave of the challenge.  Love it.</td>', 'My fave of the challenge.  Love it.', '2007-10-25 11:35:14.000000', NULL, 1),
(4195029, 604149, 39679, '<td valign="top">the contrast of this shot is really nice but there''s a lot of clutter in the forground (the train is awesome though) that distract the eye.  Overall though, a really nice shot.</td>', 'the contrast of this shot is really nice but there''s a lot of clutter in the forground (the train is awesome though) that distract the eye.  Overall though, a really nice shot.', '2007-10-25 12:45:03.000000', NULL, 1),
