(4197348, 603689, 85156, '<td valign="top">railroad tracks are a good idea, but I think the road, fences and houses are distracting and take away from the picture.  Cropping would have helped and maybe doing it in black and white.</td>', 'railroad tracks are a good idea, but I think the road, fences and houses are distracting and take away from the picture.  Cropping would have helped and maybe doing it in black and white.', '2007-10-26 12:26:28.000000', NULL, 1),
(4197351, 602910, 85156, '<td valign="top">too busy.  Try focusing on a smaller area.</td>', 'too busy.  Try focusing on a smaller area.', '2007-10-26 12:27:05.000000', NULL, 1),
(4197355, 603806, 85156, '<td valign="top">good lighting and set up.</td>', 'good lighting and set up.', '2007-10-26 12:27:45.000000', NULL, 1),
(4197356, 603430, 85156, '<td valign="top">too many moons and too dark.</td>', 'too many moons and too dark.', '2007-10-26 12:28:07.000000', NULL, 1),
