(4197360, 601932, 85156, '<td valign="top">I like the picture but don''t think it fits the challenge well. I would have had a little less sky and some more land to balance it out.</td>', 'I like the picture but don''t think it fits the challenge well. I would have had a little less sky and some more land to balance it out.', '2007-10-26 12:29:50.000000', NULL, 1),
(4197367, 603944, 85156, '<td valign="top">either put the boat in the picture or out.  Not a little of each.</td>', 'either put the boat in the picture or out.  Not a little of each.', '2007-10-26 12:35:32.000000', NULL, 1),
(4197426, 603863, 39057, '<td valign="top">Would have be a 7 if the dof was such that you could clearly see the distance. 6 ++<br/><br/><i>Message edited by author 2007-10-31 09:24:22.</i></td>', 'Would have be a 7 if the dof was such that you could clearly see the distance. 6 ++', '2007-10-26 13:03:48.000000', '2007-10-31 09:24:22.000000', 1),
(4197472, 603742, 41675, '<td valign="top">Wow! Wonderful use of natural lighting. Effective silhouette of horse in the background. An all around great photo. One of my favorites so far. Good luck in the challenge. 10</td>', 'Wow! Wonderful use of natural lighting. Effective silhouette of horse in the background. An all around great photo. One of my favorites so far. Good luck in the challenge. 10', '2007-10-26 13:27:07.000000', NULL, 1),
(4197484, 603953, 41675, '<td valign="top">For me, the overall yellow cast isn''t appealing, yet I like the composition and your idea - it shows creative thinking. I also wonder if you rotated it slightly counter-clockwise and cropped it slightly at the top to gemove that upper tan/brown corner.</td>', 'For me, the overall yellow cast isn''t appealing, yet I like the composition and your idea - it shows creative thinking. I also wonder if you rotated it slightly counter-clockwise and cropped it slightly at the top to gemove that upper tan/brown corner.', '2007-10-26 13:32:02.000000', NULL, 1),
(4197489, 604143, 41675, '<td valign="top">For me, there isn''t any correlation with your objects. I really like the ruler on the green background and the angle of it.</td>', 'For me, there isn''t any correlation with your objects. I really like the ruler on the green background and the angle of it.', '2007-10-26 13:33:47.000000', NULL, 1),
(4197495, 604111, 41675, '<td valign="top">:-) I like your title. Good entry for this challenge. For me, if there had been a person at the very end it would have added more interest for me visually.</td>', ':-) I like your title. Good entry for this challenge. For me, if there had been a person at the very end it would have added more interest for me visually.', '2007-10-26 13:35:26.000000', NULL, 1),
(4197507, 601857, 41675, '<td valign="top">For me, the weeds in the middle are too distracting. If they had been cut down so they weren''t blocking his face, I would have scored it higher. I like your idea though - shows creative thinking.</td>', 'For me, the weeds in the middle are too distracting. If they had been cut down so they weren''t blocking his face, I would have scored it higher. I like your idea though - shows creative thinking.', '2007-10-26 13:42:49.000000', NULL, 1),
(4197511, 603989, 41675, '<td valign="top">Ahhh, how sweet. For me, it''s a bit on the yellow side as far as the tones, but I really like the composition and black background.</td>', 'Ahhh, how sweet. For me, it''s a bit on the yellow side as far as the tones, but I really like the composition and black background.', '2007-10-26 13:45:49.000000', NULL, 1),
(4197513, 603447, 41675, '<td valign="top">Neat perspective and very vibrant fall colors. I like it.</td>', 'Neat perspective and very vibrant fall colors. I like it.', '2007-10-26 13:46:41.000000', NULL, 1),
(4197570, 602219, 85462, '<td valign="top">Love this!</td>', 'Love this!', '2007-10-26 14:37:49.000000', NULL, 1),
