(4198114, 603623, 85598, '<td valign="top">Beautiful nature composition, a bit too many lines on the screen though which tend to confuse the viewer''s eye</td>', 'Beautiful nature composition, a bit too many lines on the screen though which tend to confuse the viewer''s eye', '2007-10-26 19:06:34.000000', NULL, 1),
