(4200660, 604003, 83313, '<td valign="top">Nice colors and perspective. I think the crop may be a little too wide. Maybe it''s just too centered.</td>', 'Nice colors and perspective. I think the crop may be a little too wide. Maybe it''s just too centered.', '2007-10-28 01:28:10.000000', NULL, 1),
(4200662, 603921, 83313, '<td valign="top">Interesting perspective, Not as much detail coming through as I am sure this subject really has.</td>', 'Interesting perspective, Not as much detail coming through as I am sure this subject really has.', '2007-10-28 01:29:29.000000', NULL, 1),
(4200665, 603838, 83313, '<td valign="top">Nice smooth blacktop. A basic image, but well done.</td>', 'Nice smooth blacktop. A basic image, but well done.', '2007-10-28 01:30:09.000000', NULL, 1),
(4200667, 603033, 83313, '<td valign="top">This looks dull on the colors, and there is no real subject that my eye is drawn to.</td>', 'This looks dull on the colors, and there is no real subject that my eye is drawn to.', '2007-10-28 01:31:41.000000', NULL, 1),
(4200673, 603464, 83313, '<td valign="top">A good shot though not quite crisp enough. Reminds me of when I was stationed in the in the U.K., with the Air Force, and my in-laws came to visit. My father in law referred to all the roundabouts as "Runarounds". He may have been right.</td>', 'A good shot though not quite crisp enough. Reminds me of when I was stationed in the in the U.K., with the Air Force, and my in-laws came to visit. My father in law referred to all the roundabouts as "Runarounds". He may have been right.', '2007-10-28 01:33:40.000000', NULL, 1),
(4200675, 603893, 83313, '<td valign="top">Looks a little grainy, otherwise, very nice.</td>', 'Looks a little grainy, otherwise, very nice.', '2007-10-28 01:34:35.000000', NULL, 1),
(4200680, 602426, 83313, '<td valign="top">Seems to be a lot of visible artifacting, from either compression or processing. The shot itself is nicely composed, and I know it''s tough to get vertical lines to be parallel, so good job on that part.</td>', 'Seems to be a lot of visible artifacting, from either compression or processing. The shot itself is nicely composed, and I know it''s tough to get vertical lines to be parallel, so good job on that part.', '2007-10-28 01:37:29.000000', NULL, 1),
(4200684, 602490, 83313, '<td valign="top">The busted up bits of concrete take a bit away from an otherwise very good image. Nice use of shadows and b/w.</td>', 'The busted up bits of concrete take a bit away from an otherwise very good image. Nice use of shadows and b/w.', '2007-10-28 01:39:21.000000', NULL, 1),
(4200690, 603989, 83313, '<td valign="top">Nice portrait, though I''m not sure the sepia works for this and it seems too centered.</td>', 'Nice portrait, though I''m not sure the sepia works for this and it seems too centered.', '2007-10-28 01:41:21.000000', NULL, 1),
(4200693, 604128, 83313, '<td valign="top">Gorgeous scenery. I think a different crop may have done it more justice.</td>', 'Gorgeous scenery. I think a different crop may have done it more justice.', '2007-10-28 01:42:28.000000', NULL, 1),
(4200694, 603944, 83313, '<td valign="top">Seems a little hazy. Some minor adjustments would really make this pop.</td>', 'Seems a little hazy. Some minor adjustments would really make this pop.', '2007-10-28 01:43:32.000000', NULL, 1),
(4200697, 603129, 83313, '<td valign="top">Nice photo. I think it lost a lot of detail in the resampling down to 640 pixels.</td>', 'Nice photo. I think it lost a lot of detail in the resampling down to 640 pixels.', '2007-10-28 01:45:02.000000', NULL, 1),
(4200703, 602219, 83313, '<td valign="top">This is great. Wonderful lighting, colors, and the DOF works well for the idea.</td>', 'This is great. Wonderful lighting, colors, and the DOF works well for the idea.', '2007-10-28 01:46:22.000000', NULL, 1),
(4200706, 601857, 83313, '<td valign="top">Nice viewpoint. just a couple of small items that intrude on it for me:<br/>1) The weed partially covering his face.<br/>2) A couple of pieces of trash in the bike rack.</td>', 'Nice viewpoint. just a couple of small items that intrude on it for me:1) The weed partially covering his face.2) A couple of pieces of trash in the bike rack.', '2007-10-28 01:48:40.000000', NULL, 1),
